#include <string>

class Solution {
public:
    bool hasSpecialSubstring(std::string s, int k) {
        int n = s.length();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s[j] == s[i]) j++;
            if (j - i == k) return true;
            i = j;
        }
        return false;
    }
};

class Solution {
    public boolean hasSpecialSubstring(String s, int k) {
        int n = s.length();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) == s.charAt(i)) j++;
            if (j - i == k) return true;
            i = j;
        }
        return false;
    }
}

var hasSpecialSubstring = function(s, k) {
    const n = s.length;
    let i = 0;
    while (i < n) {
        let j = i;
        while (j < n && s[j] === s[i]) j++;
        if (j - i === k) return true;
        i = j;
    }
    return false;
};
